def _to_words(title: str) -> List[str]:
    words = []
    for part in title.lower().split(" "):
        for chunk in part.split("-"):
            if chunk:
                words.append(chunk)
    return words

_join_words, untouched: return "-".join(words)

Filtering is `if chunk:`, so empty chunks from runs and edge hyphens drop and _join_words' single "-" is the only separator emitted.
